<?php
namespace qqworld_collector\module\collect_filter; class decode_unicode extends filter { public function unicode_decode($name) { $pattern = '/\\\u[\w]{4}/i'; $preg = preg_match_all($pattern, $name, $matches); if ($preg) { $patterns = array(); $replacements = array(); foreach ($matches[0] as $index => $str) { if (strpos($str, '\\u') === 0) { $code = base_convert(substr($str, 2, 2), 16, 10); $code2 = base_convert(substr($str, 4), 16, 10); $c = chr($code).chr($code2); $c = mb_convert_encoding($c, 'UTF-8', 'UCS-2'); $patterns[] = $str; $replacements[] = $c; } } $name = str_replace($patterns, $replacements, $name); } return $name; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $patterns = array('\n', '\t', '\r'); $replacements = array('', '', ''); $item = str_replace($patterns, $replacements, $item); $item = $this->unicode_decode($item); return $item; } } ?>